function runTests() {
  function arrayToLinkedList(arr) {
    const dummy = new Node(0);
    let current = dummy;
    for (let i = 0; i < arr.length; i++) {
      current.next = new Node(arr[i]);
      current = current.next;
    }
    return dummy.next;
  }

  function linkedListToArray(head) {
    const result = [];
    let current = head;
    while (current) {
      result.push(current.val);
      current = current.next;
    }
    return result;
  }

  const tests = [
    // Book example
    [
      [1, 1, 1, 3, 5, 5],
      [1, 3, 5],
    ],

    // Test empty list
    [[], []],
    // Test single node
    [[1], [1]],
    // Test no duplicates
    [
      [1, 2, 3],
      [1, 2, 3],
    ],
    // Test all duplicates
    [[1, 1, 1, 1, 1], [1]],
    // Test some duplicates
    [
      [1, 1, 2, 3, 3],
      [1, 2, 3],
    ],
    // Test duplicates at start
    [
      [1, 1, 2, 3],
      [1, 2, 3],
    ],
    // Test duplicates at end
    [
      [1, 2, 3, 3],
      [1, 2, 3],
    ],
    // Test duplicates in middle
    [
